INSERT INTO content_releases VALUES('be-action-contrast-v1','published','16abac3d56a67a63413308d856889fa990e8e2bf40089399afffc55976dd7bbf',unixepoch()*1000);
INSERT INTO lessons VALUES('contrast.be-action',1,'be-action-contrast-v1',3,'A',1,'be与行为动词辨析','{}');
INSERT INTO items VALUES('contrast.be-action.identity',1,'contrast.be-action',1,'grammar.be-action-contrast','contrast-choice','choice','{"id":"contrast.be-action.identity","context":"你在介绍妈妈的职业：她是一名护士。","prompt":"哪一句准确表达妈妈的职业？","type":"choice","choices":["She is a nurse.","She does a nurse.","She a nurse."],"category":"grammar","title":"be与行为动词辨析","gradeMin":3}','{"answers":["She is a nurse."],"explanation":"职业名词前需要be连接主语：She is a nurse。does不能在这里代替is；She a nurse缺少谓语。","hint":"先判断是在说身份，还是在说做什么。","family":"contrast.be-action.identity","workshopId":"be-action-contrast"}','published');
INSERT INTO release_items VALUES('be-action-contrast-v1','contrast.be-action.identity',1);
INSERT INTO items VALUES('contrast.be-action.habit',1,'contrast.be-action',1,'grammar.be-action-contrast','contrast-choice','choice','{"id":"contrast.be-action.habit","context":"Evan每天放学后踢足球。这里说的是习惯，不是正在做的动作。","prompt":"哪一句合适？","type":"choice","choices":["Evan plays football after school.","Evan is play football after school.","Evan are plays football after school."],"category":"grammar","title":"be与行为动词辨析","gradeMin":3}','{"answers":["Evan plays football after school."],"explanation":"这里的主要动词是play。一般现在时中，Evan是第三人称单数，用plays；不能把is和动词原形play直接连在一起。","hint":"找到表达动作的动词，再看主语。","family":"contrast.be-action.habit","workshopId":"be-action-contrast"}','published');
INSERT INTO release_items VALUES('be-action-contrast-v1','contrast.be-action.habit',1);
INSERT INTO items VALUES('contrast.be-action.question-state',1,'contrast.be-action',1,'grammar.be-action-contrast','contrast-choice','choice','{"id":"contrast.be-action.question-state","context":"你想知道Nora是否已经准备好了，不是问她是否做准备工作。","prompt":"请选择问句。","type":"choice","choices":["Is Nora ready?","Does Nora ready?","Nora is ready?"],"category":"grammar","title":"be与行为动词辨析","gradeMin":3}','{"answers":["Is Nora ready?"],"explanation":"ready表示状态。陈述句Nora is ready变一般疑问句时，把is放到主语前。Does后不能直接接ready；本题练习标准的一般疑问句语序。","hint":"ready是状态词，不是动作动词。","family":"contrast.be-action.question-state","workshopId":"be-action-contrast"}','published');
INSERT INTO release_items VALUES('be-action-contrast-v1','contrast.be-action.question-state',1);
INSERT INTO items VALUES('contrast.be-action.question-action',1,'contrast.be-action',1,'grammar.be-action-contrast','contrast-input','input','{"id":"contrast.be-action.question-action","context":"Leo的习惯是骑车上学。你想向他确认。填一个词，不加标点。","prompt":"___ you ride a bike to school?","type":"input","category":"grammar","title":"be与行为动词辨析","gradeMin":3}','{"answers":["Do"],"explanation":"ride是行为动词，主语是you，一般现在时问句用Do you ride...?。Are you ride不符合这里的结构。","hint":"这句话的主要动词是ride。","family":"contrast.be-action.question-action","workshopId":"be-action-contrast"}','published');
INSERT INTO release_items VALUES('be-action-contrast-v1','contrast.be-action.question-action',1);
INSERT INTO items VALUES('contrast.be-action.short-state',1,'contrast.be-action',1,'grammar.be-action-contrast','contrast-input','input','{"id":"contrast.be-action.short-state","context":"有人问两位同学是否准备好了。回答用完整形式，填一个词。","prompt":"Are you ready? — Yes, we ___.","type":"input","category":"grammar","title":"be与行为动词辨析","gradeMin":3}','{"answers":["are"],"explanation":"问句用be问状态，简短肯定回答也用be：Yes, we are。we不能搭配is，也不能换成do。","hint":"简短回答要与问句使用的动词结构对应。","family":"contrast.be-action.short-state","workshopId":"be-action-contrast"}','published');
INSERT INTO release_items VALUES('be-action-contrast-v1','contrast.be-action.short-state',1);
INSERT INTO items VALUES('contrast.be-action.short-action',1,'contrast.be-action',1,'grammar.be-action-contrast','contrast-input','input','{"id":"contrast.be-action.short-action","context":"有人问同学们是否每天读书。回答用完整形式，填一个词。","prompt":"Do you read every day? — Yes, we ___.","type":"input","category":"grammar","title":"be与行为动词辨析","gradeMin":3}','{"answers":["do"],"explanation":"这里用Do询问read这个习惯动作，因此回答Yes, we do。Yes, we are对应be问句，不对应这个问句。","hint":"找问句开头的助动词。","family":"contrast.be-action.short-action","workshopId":"be-action-contrast"}','published');
INSERT INTO release_items VALUES('be-action-contrast-v1','contrast.be-action.short-action',1);
INSERT INTO items VALUES('contrast.be-action.agreement',1,'contrast.be-action',1,'grammar.be-action-contrast','contrast-repair','repair','{"id":"contrast.be-action.agreement","context":"Rory和我现在很累。只改一处，保留原来的意思。","prompt":"选出有误的部分，填写正确形式。","type":"repair","editing":{"parts":[{"id":"p0","text":"Rory and I"},{"id":"p1","text":"is"},{"id":"p2","text":"tired."}]},"category":"grammar","title":"be与行为动词辨析","gradeMin":3}','{"answers":["[\"p1\",\"are\"]"],"repairs":[{"partId":"p1","replacements":["are"]}],"solutionSentences":["Rory and I are tired."],"explanation":"Rory and I指两个人，相当于we，be用are。tired描述状态，所以改is为are即可，不需要额外加do。","hint":"主语包含几个人？可以换成哪个代词？","family":"contrast.be-action.agreement","workshopId":"be-action-contrast"}','published');
INSERT INTO release_items VALUES('be-action-contrast-v1','contrast.be-action.agreement',1);
INSERT INTO items VALUES('contrast.be-action.does-base',1,'contrast.be-action',1,'grammar.be-action-contrast','contrast-repair','repair','{"id":"contrast.be-action.does-base","context":"下面想问的是Maya每周日是否打网球。只改一处。","prompt":"选出有误的部分，填写正确形式。","type":"repair","editing":{"parts":[{"id":"p0","text":"Does"},{"id":"p1","text":"Maya"},{"id":"p2","text":"plays"},{"id":"p3","text":"tennis every Sunday?"}]},"category":"grammar","title":"be与行为动词辨析","gradeMin":3}','{"answers":["[\"p2\",\"play\"]"],"repairs":[{"partId":"p2","replacements":["play"]}],"solutionSentences":["Does Maya play tennis every Sunday?"],"explanation":"Does已经承担第三人称单数标记，后面的行为动词用原形play。不能同时用Does和plays。","hint":"Does后面应该接哪一种动词形式？","family":"contrast.be-action.does-base","workshopId":"be-action-contrast"}','published');
INSERT INTO release_items VALUES('be-action-contrast-v1','contrast.be-action.does-base',1);
INSERT INTO items VALUES('contrast.be-action.negative-state',1,'contrast.be-action',1,'grammar.be-action-contrast','contrast-repair','repair','{"id":"contrast.be-action.negative-state","context":"Lina现在不开心。只改一处，保留这个意思。","prompt":"选出有误的部分，填写正确形式。","type":"repair","editing":{"parts":[{"id":"p0","text":"Lina"},{"id":"p1","text":"doesn''t"},{"id":"p2","text":"happy."}]},"category":"grammar","title":"be与行为动词辨析","gradeMin":3}','{"answers":["[\"p1\",\"isn''t\"]","[\"p1\",\"is not\"]"],"repairs":[{"partId":"p1","replacements":["isn''t","is not"]}],"solutionSentences":["Lina isn''t happy."],"explanation":"happy是状态词，要用be的否定形式isn''t或is not。doesn''t后需要行为动词，不能直接接happy。","hint":"先判断happy是状态，还是动作。","family":"contrast.be-action.negative-state","workshopId":"be-action-contrast"}','published');
INSERT INTO release_items VALUES('be-action-contrast-v1','contrast.be-action.negative-state',1);
INSERT INTO items VALUES('contrast.be-action.evidence-job',1,'contrast.be-action',1,'grammar.be-action-contrast','contrast-evidence','evidence','{"id":"contrast.be-action.evidence-job","type":"evidence","context":"读三句话。先选能直接支持答案的一句，再选答案。","prompt":"Which sentence tells us what Ben''s aunt does as a job?","passage":[{"id":"s1","text":"Ben''s aunt is a bus driver."},{"id":"s2","text":"She is at home today."},{"id":"s3","text":"She reads a book in the morning."}],"choices":["She is a bus driver.","She is at home.","She reads a book."],"category":"grammar","title":"be与行为动词辨析","gradeMin":3}','{"answers":["[\"s1\",\"she is a bus driver.\"]"],"evidenceTargets":["s1"],"evidenceSolutions":[{"sentenceId":"s1","answer":"She is a bus driver."}],"explanation":"第一句说明职业，直接支持bus driver。第二句中的is说明地点；第三句说明读书的动作。三个句子都有意义，但只有第一句回答职业问题。","hint":"寻找说明职业的名词，而不是只找is这个词。","family":"contrast.be-action.evidence-job","workshopId":"be-action-contrast"}','published');
INSERT INTO release_items VALUES('be-action-contrast-v1','contrast.be-action.evidence-job',1);
INSERT INTO items VALUES('contrast.be-action.location-order',1,'contrast.be-action',1,'grammar.be-action-contrast','contrast-order','order','{"id":"contrast.be-action.location-order","type":"order","context":"你想知道对方的姐姐是否在图书馆。用所有单词组成标准问句。","prompt":"把问句按顺序排好。","tokens":["your","library","Is","sister","the","in","?"],"punctuationTokens":true,"category":"grammar","title":"be与行为动词辨析","gradeMin":3}','{"answers":["Is your sister in the library?"],"explanation":"这里用be询问地点，结构是Is + your sister + in the library?。in the library是地点短语，the不能遗漏。","hint":"先放be，再放完整主语，最后放地点短语。","family":"contrast.be-action.location-order","workshopId":"be-action-contrast"}','published');
INSERT INTO release_items VALUES('be-action-contrast-v1','contrast.be-action.location-order',1);
INSERT INTO items VALUES('contrast.be-action.transfer-location',1,'contrast.be-action',1,'grammar.be-action-contrast','contrast-choice','choice','{"id":"contrast.be-action.transfer-location","context":"在校外活动点，工作人员问两位孩子是否在他们的班级中。孩子们回答：不，我们在另一个班。","prompt":"选择与回答相符的问句：— No, we aren''t. We''re in another class.","type":"choice","choices":["Are you in my class?","Do you in my class?","Is you in my class?"],"category":"grammar","title":"be与行为动词辨析","gradeMin":3}','{"answers":["Are you in my class?"],"explanation":"回答we aren''t与be问句对应；询问班级归属用Are you in my class?。Do后不能直接接in my class；you也不能与is搭配。","hint":"把回答还原成肯定陈述句，再想怎样提问。","family":"contrast.be-action.transfer-location","workshopId":"be-action-contrast"}','published');
INSERT INTO release_items VALUES('be-action-contrast-v1','contrast.be-action.transfer-location',1);
